const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}

const nombre   = String(body.nombre   || '').trim();
const telefono = String(body.telefono || '').trim();
const personas = parseInt(body.personas) || 0;
const fecha    = String(body.fecha    || '').trim(); // yyyy-mm-dd
const franja   = String(body.franja   || '').trim(); // almuerzo | cena
const notas    = String(body.notas    || '').trim();

if (!nombre || !telefono || !personas || !fecha || !franja) {
  return [{ json: { error: true, mensaje: 'Faltan datos para crear la reserva.' } }];
}

// ID de reserva
const fechaCompacta = fecha.replace(/-/g, '');
const inicialFranja = franja === 'almuerzo' ? 'A' : 'C';
const aleatorio     = Math.random().toString(36).toUpperCase().substring(2, 6);
const idReserva     = `${fechaCompacta}${inicialFranja}-${aleatorio}`;

// Fecha formateada para Sheets (dd/mm/yyyy)
const [year, month, day] = fecha.split('-');
const fechaFormateada = `${day}/${month}/${year}`;

// Fechas-hora para Google Calendar (formato ISO 8601 con zona horaria)
// Almuerzo: 13:30 - 16:00 | Cena: 20:30 - 23:59
const horaInicio = franja === 'almuerzo' ? '13:30:00' : '20:30:00';
const horaFin    = franja === 'almuerzo' ? '16:00:00' : '23:59:00';
const fechaHoraInicio = `${fecha}T${horaInicio}`;
const fechaHoraFin    = `${fecha}T${horaFin}`;

// Título y descripción del evento de calendario
const apellido  = nombre.split(' ').pop();
const tituloEvento = `Ekis — ${apellido} (${personas} pers.) — ${franja}`;
const descripcion  = `Reserva ID: ${idReserva}\nNombre: ${nombre}\nTeléfono: ${telefono}\nPersonas: ${personas}\nFranja: ${franja}${notas ? '\nNotas: ' + notas : ''}`;

// Texto natural para confirmar a Carmen
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const diaSemana  = diasSemana[new Date(fecha).getDay()];
const franjaTexto = franja === 'almuerzo' ? 'a mediodía' : 'por la noche';
const mensajeConfirmacion = `Reserva confirmada a nombre de ${apellido}, para ${personas} ${personas === 1 ? 'persona' : 'personas'}, el ${diaSemana} ${franjaTexto}. Te esperamos.`;

const ahora = new Date().toISOString().replace('T', ' ').substring(0, 19);

return [{ json: {
  error: false,
  idReserva, nombre, apellido, telefono, personas, fecha, franja, notas,
  fechaFormateada,
  fechaHoraInicio, fechaHoraFin,
  tituloEvento, descripcion,
  mensajeConfirmacion,
  ahora
}}];
